import"./api-harsJktA.js";document.addEventListener("DOMContentLoaded",function(){(async function(){if(await api.waitForAuth(),!api.getToken()){window.location.href="../login/index.html";return}try{await api.me()}catch{api.clearSession(),window.location.href="../login/index.html";return}const e=new URLSearchParams(window.location.search).get("edit"),a=document.getElementById("entry-title"),l=document.getElementById("page-heading");if(e){l.textContent="Edit Entry";try{const t=await api.getJournalEntry(e);t.entry&&(a.value=t.entry.title||"",document.getElementById("writing").value=t.entry.text||"",document.getElementById("mood").value=t.entry.mood||"😐")}catch(t){console.error(t)}}document.getElementById("save-btn").addEventListener("click",async function(){const t=a.value.trim(),n=document.getElementById("writing").value.trim();if(!n){alert("Please write something in the journal before saving.");return}const r=t||"Journal Entry",i=new Date().toLocaleDateString();try{e?await api.updateJournalEntry(e,{text:n,date:i,title:r,mood:document.getElementById("mood").value}):await api.createJournalEntry({text:n,date:i,title:r,mood:document.getElementById("mood").value}),window.location.href="../dashboard/index.html"}catch(d){console.error(d),alert(d.message||"Could not save entry.")}})})().catch(function(o){console.error(o)})});
